  FaAppleAlt, FaDumbbell, FaPhone, FaMapMarkerAlt, FaNotesMedical,
  FaBrain, FaSmile, FaExclamationTriangle, FaChartLine, FaCalendarAlt,
  FaUniversity, FaLaptop, FaCoffee, FaMoon, FaSun, FaBell,
  FaUserMd, FaCheckCircle, FaInfoCircle, FaRuler, FaWeight, FaBirthdayCake
} from 'react-icons/fa';

function Profile() {
  const navigate = useNavigate();
  const [user, setUser] = useState({
    name: '',
    email: '',
    joined: '',
    avatar: null,
    avatarCategory: null
  });
  
  // Student Mental Health Information
  const [studentInfo, setStudentInfo] = useState({
    // Academic Information
    studentId: '',
    course: '',
    year: '',
    semester: '',
    collegeName: '',
    department: '',
    
    // Academic Stress Factors
    currentGPA: '',
    examStress: '',
    assignmentLoad: '',
    studyHoursPerDay: '',
    attendance: '',
    
    // Mental Health Indicators
    primaryConcern: '',
    anxietyLevel: '',
    sleepQuality: '',
    sleepHours: '',
    appetite: '',
    energyLevel: '',
    concentrationIssues: '',
    socialWithdrawal: '',
    
    // Lifestyle Factors
    exerciseFrequency: '',
    socialInteraction: '',
    screenTime: '',
    caffeineIntake: '',
    mealRegularity: '',
    
    // Support System
    familySupport: '',
    friendSupport: '',
    counselorAccess: '',
    previousTherapy: '',
    
    // Emergency Contact
    emergencyName: '',
    emergencyRelation: '',
    emergencyPhone: '',
    
    // Goals
    shortTermGoal: '',
    longTermGoal: ''
  });
  
  const [showAvatarPicker, setShowAvatarPicker] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [customImageUrl, setCustomImageUrl] = useState('');
  const [showUrlInput, setShowUrlInput] = useState(false);
  const [isEditingName, setIsEditingName] = useState(false);
  const [newName, setNewName] = useState('');
  const [isEditingStudent, setIsEditingStudent] = useState(false);
  const [tempStudentInfo, setTempStudentInfo] = useState({});

  // Avatar arrays
  const boyAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/men/1.jpg', name: 'Alex' },
    { id: 2, url: 'https://randomuser.me/api/portraits/men/2.jpg', name: 'Ben' },
    { id: 3, url: 'https://randomuser.me/api/portraits/men/3.jpg', name: 'Charlie' },
    { id: 4, url: 'https://randomuser.me/api/portraits/men/4.jpg', name: 'David' },
    { id: 5, url: 'https://randomuser.me/api/portraits/men/5.jpg', name: 'Ethan' },
    { id: 6, url: 'https://randomuser.me/api/portraits/men/6.jpg', name: 'Frank' },
  ];

  const girlAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/women/1.jpg', name: 'Emma' },
    { id: 2, url: 'https://randomuser.me/api/portraits/women/2.jpg', name: 'Sophia' },
    { id: 3, url: 'https://randomuser.me/api/portraits/women/3.jpg', name: 'Olivia' },
    { id: 4, url: 'https://randomuser.me/api/portraits/women/4.jpg', name: 'Ava' },
    { id: 5, url: 'https://randomuser.me/api/portraits/women/5.jpg', name: 'Mia' },
    { id: 6, url: 'https://randomuser.me/api/portraits/women/6.jpg', name: 'Isabella' },
  ];

  const customAvatars = [
    { id: 1, url: 'https://i.pinimg.com/736x/a1/27/73/a1277303ec49ee936b2ba11bb3a98a18.jpg', name: 'Cartoon 1', category: 'cartoon' },
    { id: 2, url: 'https://i1-c.pinimg.com/1200x/67/ef/9d/67ef9d9bb1b009281379840a737c811f.jpg', name: 'Cartoon 2', category: 'cartoon' },
  ];

  // Options for dropdowns
  const years = ['1st Year', '2nd Year', '3rd Year', '4th Year', '5th Year', 'Masters', 'PhD'];
  const concernOptions = [
    'Academic Pressure', 'Exam Anxiety', 'Time Management', 'Procrastination',
    'Social Isolation', 'Homesickness', 'Financial Stress', 'Career Confusion',
    'Relationship Issues', 'Sleep Problems', 'Low Self-esteem', 'Burnout'
  ];
  const stressLevels = ['Very Low', 'Low', 'Moderate', 'High', 'Very High'];
  const sleepQualityOptions = ['Excellent', 'Good', 'Fair', 'Poor', 'Very Poor'];
  const exerciseOptions = ['Daily', '3-5 times/week', '1-2 times/week', 'Rarely', 'Never'];
  const supportLevels = ['Very Supportive', 'Supportive', 'Neutral', 'Not Supportive', 'No Support'];

  useEffect(() => {
    const savedAvatar = localStorage.getItem('userAvatar');
    const savedCategory = localStorage.getItem('userAvatarCategory');
    const savedName = localStorage.getItem('userName');
    const savedStudentInfo = localStorage.getItem('studentInfo');
    
    setUser({
      name: savedName || 'User',
      email: localStorage.getItem('userEmail') || 'user@example.com',
      joined: new Date().toLocaleDateString(),
      avatar: savedAvatar,
      avatarCategory: savedCategory
    });
    setNewName(savedName || 'User');
    
    if (savedStudentInfo) {
      setStudentInfo(JSON.parse(savedStudentInfo));
    }
  }, []);

  const stats = [
    { icon: <FaFire color="#e74c3c" />, value: '12', label: 'Day Streak' },
    { icon: <FaTrophy color="#f39c12" />, value: '8', label: 'Badges Earned' },
    { icon: <FaClock color="#3498db" />, value: '245', label: 'Focus Minutes' },
    { icon: <FaHeart color="#e84393" />, value: '156', label: 'Moods Logged' },
  ];

  // Handle name edit
  const handleEditName = () => {
    setIsEditingName(true);
    setNewName(user.name);
  };

  const handleSaveName = () => {
    if (newName.trim()) {
      setUser({ ...user, name: newName.trim() });
      localStorage.setItem('userName', newName.trim());
      setIsEditingName(false);
    }
  };

  const handleCancelEdit = () => {
    setIsEditingName(false);
    setNewName(user.name);
  };

  // Handle Student Info Edit
  const handleEditStudent = () => {
    setTempStudentInfo({ ...studentInfo });
    setIsEditingStudent(true);
  };

  const handleSaveStudent = () => {
    setStudentInfo(tempStudentInfo);
    localStorage.setItem('studentInfo', JSON.stringify(tempStudentInfo));
    setIsEditingStudent(false);
  };

  const handleCancelStudent = () => {
    setIsEditingStudent(false);
  };

  const handleStudentChange = (field, value) => {
    setTempStudentInfo({ ...tempStudentInfo, [field]: value });
  };

  // Avatar handlers
  const handleUrlSubmit = () => {
    if (customImageUrl.trim()) {
      setUser({ ...user, avatar: customImageUrl, avatarCategory: 'custom' });
      localStorage.setItem('userAvatar', customImageUrl);
      localStorage.setItem('userAvatarCategory', 'custom');
      setShowAvatarPicker(false);
      setCustomImageUrl('');
      setShowUrlInput(false);
    }
  };

  const handleImageUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imageData = reader.result;
        setUser({ ...user, avatar: imageData, avatarCategory: 'uploaded' });
        localStorage.setItem('userAvatar', imageData);
        localStorage.setItem('userAvatarCategory', 'uploaded');
        setShowAvatarPicker(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAvatarSelect = (avatarUrl, category) => {
    setUser({ ...user, avatar: avatarUrl, avatarCategory: category });
    localStorage.setItem('userAvatar', avatarUrl);
    localStorage.setItem('userAvatarCategory', category);
    setShowAvatarPicker(false);
    setSelectedCategory(null);
  };

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userAvatar');
    localStorage.removeItem('userAvatarCategory');
    localStorage.removeItem('studentInfo');
    navigate('/');
  };

  // Render form field helper
  const renderField = (label, field, type = 'text', options = null) => {
    const value = isEditingStudent ? tempStudentInfo[field] : studentInfo[field];
    
    if (!isEditingStudent) {
      return <p style={styles.fieldValue}>{value || 'Not provided'}</p>;
    }
    
    if (options) {
      return (
        <select
          value={value || ''}
          onChange={(e) => handleStudentChange(field, e.target.value)}
          style={styles.select}
        >
          <option value="">Select {label}</option>
          {options.map(opt => (
            <option key={opt} value={opt}>{opt}</option>
          ))}
        </select>
      );
    }
    
    if (type === 'textarea') {
      return (
        <textarea
          value={value || ''}
          onChange={(e) => handleStudentChange(field, e.target.value)}
          placeholder={`Enter ${label}`}
          style={styles.textarea}
          rows="3"
        />
      );
    }
    
    if (type === 'number') {
      return (
        <input
          type="number"
          value={value || ''}
          onChange={(e) => handleStudentChange(field, e.target.value)}
          placeholder={`Enter ${label}`}
          style={styles.input}
        />
      );
    }
    
    return (
      <input
        type={type}
        value={value || ''}
        onChange={(e) => handleStudentChange(field, e.target.value)}
        placeholder={`Enter ${label}`}
        style={styles.input}
      />
    );
  };

  const currentStudentInfo = isEditingStudent ? tempStudentInfo : studentInfo;

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Profile</h1>
          <p style={styles.subtitle}>Manage your account and student mental health information</p>
        </div>

        {/* Avatar Card */}
        <div style={styles.avatarCard}>
          <div style={styles.avatarContainer}>
            <div style={styles.avatarWrapper}>
              {user.avatar ? (
                <img src={user.avatar} alt="Avatar" style={styles.avatarImage} />
              ) : (
                <div style={styles.avatarPlaceholder}>
                  <FaUser size={50} color="#ccc" />
                </div>
              )}
              <button 
                style={styles.editAvatarBtn}
                onClick={() => setShowAvatarPicker(!showAvatarPicker)}
              >
                <FaCamera size={16} />
              </button>
            </div>

            <div style={styles.nameContainer}>
              {isEditingName ? (
                <div style={styles.editNameContainer}>
                  <input
                    type="text"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    style={styles.nameInput}
                    autoFocus
                    onKeyPress={(e) => e.key === 'Enter' && handleSaveName()}
                  />
                  <button onClick={handleSaveName} style={styles.saveNameBtn}>
                    <FaSave />
                  </button>
                  <button onClick={handleCancelEdit} style={styles.cancelNameBtn}>
                    <FaTimes />
                  </button>
                </div>
              ) : (
                <div style={styles.nameDisplay}>
                  <h2 style={styles.userName}>{user.name}</h2>
                  <button onClick={handleEditName} style={styles.editNameBtn}>
                    <FaEdit size={16} />
                  </button>
                </div>
              )}
            </div>

            <div style={styles.userInfo}>
              <div style={styles.infoRow}><FaEnvelope /> {user.email}</div>
              <div style={styles.infoRow}><FaCalendar /> Joined {user.joined}</div>
            </div>
          </div>

          {/* Avatar Picker Popup */}
          {showAvatarPicker && (
            <div style={styles.avatarPicker}>
              <div style={styles.pickerHeader}>
                <h4>Choose Your Avatar</h4>
                <button onClick={() => setShowAvatarPicker(false)} style={styles.closeBtn}>✕</button>
              </div>
              <div style={styles.uploadSection}>
                <label style={styles.uploadBtn}>
                  <FaUpload /> Upload Photo
                  <input type="file" accept="image/*" onChange={handleImageUpload} style={{ display: 'none' }} />
                </label>
                <button style={styles.urlBtn} onClick={() => setShowUrlInput(!showUrlInput)}>
                  <FaImage /> Use Image URL
                </button>
              </div>
              {showUrlInput && (
                <div style={styles.urlInputContainer}>
                  <input type="text" placeholder="Paste image URL here..." value={customImageUrl} onChange={(e) => setCustomImageUrl(e.target.value)} style={styles.urlInput} />
                  <button onClick={handleUrlSubmit} style={styles.urlSubmitBtn}>Add</button>
                </div>
              )}
              {!selectedCategory ? (
                <>
                  <div style={styles.categoryGrid}>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('boys')}>
                      <div style={styles.categoryIcon}><FaMars size={40} color="#3498db" /></div>
                      <h4>Boys</h4>
                    </div>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('girls')}>
                      <div style={styles.categoryIcon}><FaVenus size={40} color="#e84393" /></div>
                      <h4>Girls</h4>
                    </div>
                  </div>
                  <div style={styles.customSection}>
                    <h4 style={styles.customTitle}>🎨 More Avatars</h4>
                    <div style={styles.avatarGrid}>
                      {customAvatars.map((avatar) => (
                        <div key={avatar.id} style={styles.avatarOption} onClick={() => handleAvatarSelect(avatar.url, avatar.category)}>
                          <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                        </div>
                      ))}
                    </div>
                  </div>
                </>
              ) : (
                <>
                  <button onClick={() => setSelectedCategory(null)} style={styles.backBtn}>← Back</button>
                  <div style={styles.avatarGrid}>
                    {(selectedCategory === 'boys' ? boyAvatars : girlAvatars).map((avatar) => (
                      <div key={avatar.id} style={styles.avatarOption} onClick={() => handleAvatarSelect(avatar.url, selectedCategory)}>
                        <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                      </div>
                    ))}
                  </div>
                </>
              )}
              {user.avatar && (
                <button onClick={() => {
                  setUser({ ...user, avatar: null, avatarCategory: null });
                  localStorage.removeItem('userAvatar');
                  localStorage.removeItem('userAvatarCategory');
                  setShowAvatarPicker(false);
                }} style={styles.removeBtn}>
                  <FaTrash /> Remove Avatar
                </button>
              )}
            </div>
          )}
        </div>

        {/* Student Mental Health Information Section */}
        <div style={styles.studentSection}>
          <div style={styles.sectionHeader}>
            <h3 style={styles.sectionTitle}>
              <FaGraduationCap /> Student Mental Health Profile
            </h3>
            {!isEditingStudent ? (
              <button onClick={handleEditStudent} style={styles.editSectionBtn}>
                <FaEdit /> Edit Information
              </button>
            ) : (
              <div style={styles.sectionActions}>
                <button onClick={handleSaveStudent} style={styles.saveSectionBtn}>
                  <FaSave /> Save All
                </button>
                <button onClick={handleCancelStudent} style={styles.cancelSectionBtn}>
                  <FaTimes /> Cancel
                </button>
              </div>
            )}
          </div>

          {/* Academic Information */}
          <div style={styles.subsection}>
            <h4 style={styles.subsectionTitle}><FaUniversity /> Academic Information</h4>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.label}><FaUser /> Student ID</label>
                {renderField('Student ID', 'studentId')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaBook /> Course/Program</label>
                {renderField('Course', 'course')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaGraduationCap /> Year</label>
                {renderField('Year', 'year', 'select', years)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaCalendarAlt /> Semester</label>
                {renderField('Semester', 'semester')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaUniversity /> College Name</label>
                {renderField('College Name', 'collegeName')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaLaptop /> Department</label>
                {renderField('Department', 'department')}
              </div>
            </div>
          </div>

          {/* Academic Stress Factors */}
          <div style={styles.subsection}>
            <h4 style={styles.subsectionTitle}><FaExclamationTriangle /> Academic Stress Factors</h4>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.label}><FaChartLine /> Current GPA/CGPA</label>
                {renderField('Current GPA', 'currentGPA')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaExclamationTriangle /> Exam Stress Level</label>
                {renderField('Exam Stress', 'examStress', 'select', stressLevels)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaBook /> Assignment Load</label>
                {renderField('Assignment Load', 'assignmentLoad', 'select', ['Very Light', 'Light', 'Moderate', 'Heavy', 'Very Heavy'])}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaClockIcon /> Study Hours/Day</label>
                {renderField('Study Hours', 'studyHoursPerDay', 'number')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaChartLine /> Attendance (%)</label>
                {renderField('Attendance', 'attendance', 'number')}
              </div>
            </div>
          </div>

          {/* Mental Health Indicators */}
          <div style={styles.subsection}>
            <h4 style={styles.subsectionTitle}><FaBrain /> Mental Health Indicators</h4>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.label}><FaBrain /> Primary Concern</label>
                {renderField('Primary Concern', 'primaryConcern', 'select', concernOptions)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaSmile /> Anxiety Level</label>
                {renderField('Anxiety Level', 'anxietyLevel', 'select', stressLevels)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaMoon /> Sleep Quality</label>
                {renderField('Sleep Quality', 'sleepQuality', 'select', sleepQualityOptions)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaBed /> Sleep Hours/Night</label>
                {renderField('Sleep Hours', 'sleepHours', 'number')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaAppleAlt /> Appetite</label>
                {renderField('Appetite', 'appetite', 'select', ['Normal', 'Increased', 'Decreased', 'No Appetite'])}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaChartLine /> Energy Level</label>
                {renderField('Energy Level', 'energyLevel', 'select', ['Very High', 'High', 'Normal', 'Low', 'Very Low'])}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaBrain /> Concentration Issues</label>
                {renderField('Concentration Issues', 'concentrationIssues', 'select', ['Never', 'Rarely', 'Sometimes', 'Often', 'Always'])}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaUsers /> Social Withdrawal</label>
                {renderField('Social Withdrawal', 'socialWithdrawal', 'select', ['Never', 'Rarely', 'Sometimes', 'Often', 'Always'])}
              </div>
            </div>
          </div>

          {/* Lifestyle Factors */}
          <div style={styles.subsection}>
            <h4 style={styles.subsectionTitle}><FaCoffee /> Lifestyle Factors</h4>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.label}><FaDumbbell /> Exercise Frequency</label>
                {renderField('Exercise Frequency', 'exerciseFrequency', 'select', exerciseOptions)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaUsers /> Social Interaction</label>
                {renderField('Social Interaction', 'socialInteraction', 'select', ['Very Active', 'Active', 'Moderate', 'Limited', 'Isolated'])}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaLaptop /> Daily Screen Time (hours)</label>
                {renderField('Screen Time', 'screenTime', 'number')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaCoffee /> Caffeine Intake</label>
                {renderField('Caffeine Intake', 'caffeineIntake')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaAppleAlt /> Meal Regularity</label>
                {renderField('Meal Regularity', 'mealRegularity', 'select', ['Regular', 'Sometimes Skipped', 'Often Skipped', 'Very Irregular'])}
              </div>
            </div>
          </div>

          {/* Support System */}
          <div style={styles.subsection}>
            <h4 style={styles.subsectionTitle}><FaHeart /> Support System</h4>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.label}><FaHome /> Family Support</label>
                {renderField('Family Support', 'familySupport', 'select', supportLevels)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaUsers /> Friend Support</label>
                {renderField('Friend Support', 'friendSupport', 'select', supportLevels)}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaUserMd /> Counselor Access</label>
                {renderField('Counselor Access', 'counselorAccess', 'select', ['Easily Accessible', 'Available', 'Limited', 'Not Available'])}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaNotesMedical /> Previous Therapy</label>
                {renderField('Previous Therapy', 'previousTherapy')}
              </div>
            </div>
          </div>

          {/* Emergency Contact */}
          <div style={styles.subsection}>
            <h4 style={styles.subsectionTitle}><FaPhone /> Emergency Contact</h4>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.label}><FaUser /> Contact Name</label>
                {renderField('Emergency Name', 'emergencyName')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaUsers /> Relationship</label>
                {renderField('Relation', 'emergencyRelation')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}><FaPhone /> Phone Number</label>
                {renderField('Emergency Phone', 'emergencyPhone')}
              </div>
            </div>
          </div>

          {/* Goals */}
          <div style={styles.subsection}>
            <h4 style={styles.subsectionTitle}><FaBell /> Mental Health Goals</h4>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.label}>Short-term Goals</label>
                {renderField('Short-term Goal', 'shortTermGoal', 'textarea')}
              </div>
              <div style={styles.formField}>
                <label style={styles.label}>Long-term Goals</label>
                {renderField('Long-term Goal', 'longTermGoal', 'textarea')}
              </div>
            </div>
          </div>

          {/* Mental Health Tip */}
          <div style={styles.tipCard}>
            <FaHeart color="#e84393" size={20} />
            <p style={styles.tipText}>💡 Remember: Your mental health matters. Reach out to campus counseling services if you need support. You're not alone!</p>
          </div>
        </div>

        {/* Stats Grid */}
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statIcon}>{stat.icon}</div>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Menu Card */}
        <div style={styles.menuCard}>
          <h3 style={styles.menuTitle}>Settings</h3>
          <button onClick={handleLogout} style={styles.logoutBtn}>
            <FaSignOutAlt /> Logout
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
  },
  content: {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    paddingTop: '80px',
    paddingBottom: '40px',
  },
  header: {
    textAlign: 'center',
    marginBottom: '30px',
    color: 'white',
  },
  title: {
    fontSize: '32px',
    marginBottom: '10px',
  },
  subtitle: {
    fontSize: '14px',
    opacity: 0.9,
  },
  avatarCard: {
    background: 'white',
    borderRadius: '20px',
    padding: '30px',
    marginBottom: '20px',
    position: 'relative',
